import { z } from "zod";
import { ZId } from "@formbricks/types/common";
import { ZAITranslationField } from "@/modules/ee/ai-translation/lib/translate-fields";

/**
 * Language names go into the model's instructions, so they are bounded like every other request string
 * (ENG-1652); a language's display name is a few words. Field paths are generated by the editor
 * (`blocks.0.elements.1.headline`). The number of fields is held to the request-wide array budget, and
 * their text to the body limit.
 */
const LANGUAGE_NAME_MAX_LENGTH = 255;
const FIELD_PATH_MAX_LENGTH = 1024;

export const ZAITranslationAvailabilityQuery = z.object({ surveyId: ZId }).strict();

export const ZAITranslationWorkspaceQuery = z.object({ workspaceId: ZId }).strict();

/** `POST /api/internal/ai-translations?workspaceId=` body: the default-language texts to translate. */
export const ZAITranslationBody = z
  .object({
    fields: z
      .array(ZAITranslationField.extend({ path: z.string().max(FIELD_PATH_MAX_LENGTH) }).strict())
      .min(1),
    sourceLanguage: z.string().min(1).max(LANGUAGE_NAME_MAX_LENGTH),
    targetLanguage: z.string().min(1).max(LANGUAGE_NAME_MAX_LENGTH),
  })
  .strict();

export type TAITranslationBody = z.infer<typeof ZAITranslationBody>;
